"""Weekly timesheet rows built from a list of shifts."""

from hourglass.schedule import worker_minutes
from hourglass.errors import ProjectError
from collections import Counter

def check_shifts(shifts):
    if not shifts:
        raise ProjectError("no shifts given")
    for shift in shifts:
        if not shift.worker.strip():
            raise ProjectError("blank worker name")

def format_row(name, count, minutes):
    hours = minutes / 60
    return f"{name}: {count} shifts, {hours:.1f} hours"

def busiest_first(totals):
    rank = lambda name: (-totals[name], name)
    return sorted(totals, key=rank)

def timesheet_rows(shifts):
    check_shifts(shifts)
    totals = worker_minutes(shifts)
    counts = Counter(item.worker for item in shifts)
    return [
        format_row(name, counts[name], totals[name])
        for name in busiest_first(totals)
    ]

