import unittest

from hourglass.timesheet import timesheet_rows
from hourglass.models import Shift, Span
from hourglass.errors import ProjectError

def make_shift(worker, start, end):
    return Shift(worker, "mon", Span(start * 60, end * 60))

class TimesheetTests(unittest.TestCase):
    def setUp(self):
        self.shifts = [
            make_shift("Ana", 9, 10),
            make_shift("Brisa", 9, 12),
            make_shift("Ana", 13, 14)
        ]

    def test_busiest_first(self):
        rows = timesheet_rows(self.shifts)
        self.assertEqual(rows[0], 
            "Brisa: 1 shifts, 3.0 hours")
        self.assertEqual(
            rows[1], "Ana: 2 shifts, 2.0 hours")

    def test_one_decimal(self):
        shift = Shift("Ana", "tue", Span(0, 100))
        rows = timesheet_rows([shift])
        self.assertEqual(rows, ["Ana: 1 shifts, 1.7 hours"])

    def test_empty(self):
        with self.assertRaises(ProjectError):
            timesheet_rows([])

    def test_blank_worker(self):
        with self.assertRaises(ProjectError):
            timesheet_rows([make_shift("  ", 9, 10)])
